    else:
        children.extend(['---',item('启动 OpenCodex 代理',sfimage='play.fill',**act('start')),
                         item('修复自启动服务',sfimage='wrench.and.screwdriver',**act('repair')),
                         item('查看 ocx status',sfimage='terminal',**act('status'))])
